'use strict';

// Coarse public uptime for the homepage P-02 "Wallet" lamp: whole UTC days since the pool wallet
// was last UNLOCKED, beside the node's and the pool's `up_days`. Same contract as the node
// (design §20.5): an integer via upDaysFrom (flips only at 00:00 UTC, understates by up to a day,
// never overstates), or null for unknown. Never a timestamp, never seconds, never 0 for unknown.
//
// The unlock time comes from a stamp that the toolkit's unlock helper (pool-wallet-unlock.js,
// generated by scripts/lib/07_lib_pool_wallet.sh) writes after every successful open_wallet. The
// helper runs at boot, on the watchdog's "wallet locked" signal and on a manual unlock. Both
// listener starters (the boot script and pw_listener_start) delete the stamp before they start a
// new listener, so a start whose unlock never ran reads as unknown, not as the previous run, even
// when the backend later opens the wallet itself. The stamp survives a pool restart and moves
// whenever grin-wallet itself restarts. The helper runs as root and writes into a root-owned
// directory, because the wallet dir belongs to grinpool. The "Pool svc" uptime is NOT here: it is
// NodeAvailability.poolUpDaysPublic(), the same figure as admin → Node availability.

const fs = require('fs');
const { upDaysFrom } = require('./node-availability');

const nowS = () => Math.floor(Date.now() / 1000);
const GENESIS_TS = 1547510400;   // grin mainnet genesis; an earlier stamp is not a real unlock

function unlockStampPath(network) {
  if (process.env.POOL_WALLET_UNLOCK_STAMP) return process.env.POOL_WALLET_UNLOCK_STAMP;
  const net = network === 'testnet' ? 'testnet' : 'mainnet';
  return `/opt/grin/lib/pubpool-${net}-status/wallet_unlocked_at`;
}

// The stamp as epoch seconds, or null when it is missing, unreadable or not a plausible time.
function readUnlockStamp(file, now = nowS()) {
  try {
    const raw = fs.readFileSync(file, 'utf8').trim();
    if (!/^\d{1,12}$/.test(raw)) return null;
    const t = Number(raw);
    return Number.isSafeInteger(t) && t >= GENESIS_TS && t <= now ? t : null;
  } catch (_) {
    return null;
  }
}

// `reachableNow` is the caller's own probe result: not reachable now means null, whatever the
// stamp says (same rule as NodeAvailability.upDaysPublic).
function walletUpDays(reachableNow, network, now = nowS()) {
  if (reachableNow !== true) return null;
  const since = readUnlockStamp(unlockStampPath(network), now);
  return since === null ? null : upDaysFrom(since, now);
}

module.exports = { unlockStampPath, readUnlockStamp, walletUpDays };
